"""Synthetic Wyscout open-data files for tests (generated by code; no provider data).

One competition, one match: home 1-0 away, with a kick-off, passes, a goal, a keeper's save
attempt, a corner, a goal kick, a duel, a foul and a missed penalty. Coordinates use Wyscout's
0-100 scale, each team attacking left to right, y from the top.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

COMPETITION_ID, SEASON_ID, MATCH_ID = 9998, 1, 990001
HOME, AWAY = 2001, 2002
COMPETITIONS = {COMPETITION_ID: ("Fixture", 1, 11, 22)}  # matches, events, players


def pid(team: int, n: int) -> int:
    """Player id for shirt slot ``n`` (1-11)."""
    return (30_000 if team == HOME else 40_000) + n


def _ev(
    i: int,
    period: str,
    sec: float,
    name: str,
    eid: int,
    sub: str,
    sid: int,
    team: int,
    n: int,
    start: tuple[int, int],
    end: tuple[int, int],
    tags: list[int],
) -> dict[str, Any]:
    return {
        "id": 500_000 + i,
        "matchId": MATCH_ID,
        "matchPeriod": period,
        "eventSec": sec,
        "eventId": eid,
        "eventName": name,
        "subEventId": sid,
        "subEventName": sub,
        "teamId": team,
        "playerId": pid(team, n),
        "positions": [{"x": start[0], "y": start[1]}, {"x": end[0], "y": end[1]}],
        "tags": [{"id": t} for t in tags],
    }


def events() -> list[dict[str, Any]]:
    """The match's events, in order."""
    rows = [
        ("1H", 1.0, "Pass", 8, "Simple pass", 85, HOME, 10, (50, 50), (40, 50), [1801]),
        ("1H", 4.0, "Pass", 8, "Simple pass", 85, HOME, 6, (40, 50), (70, 40), [1801]),
        ("1H", 9.0, "Shot", 10, "Shot", 100, HOME, 9, (88, 50), (100, 50), [101, 402, 1801]),
        ("1H", 9.5, "Save attempt", 9, "Reflexes", 90, AWAY, 1, (0, 0), (100, 100), [101, 1802]),
        ("1H", 200.0, "Free Kick", 3, "Corner", 30, AWAY, 7, (100, 0), (90, 50), [1802]),
        ("1H", 205.0, "Free Kick", 3, "Goal kick", 34, HOME, 1, (0, 0), (60, 30), [1801]),
        (
            "1H",
            300.0,
            "Duel",
            1,
            "Ground defending duel",
            12,
            HOME,
            3,
            (30, 60),
            (30, 60),
            [703, 1801],
        ),
        ("1H", 400.0, "Foul", 2, "Foul", 20, AWAY, 4, (55, 40), (55, 40), [1702]),
        ("2H", 1.0, "Pass", 8, "Simple pass", 85, AWAY, 10, (50, 50), (40, 50), [1801]),
        ("2H", 900.0, "Free Kick", 3, "Penalty", 35, HOME, 9, (89, 50), (100, 60), [402, 1802]),
        ("2H", 905.0, "Pass", 8, "Simple pass", 85, AWAY, 2, (20, 30), (45, 20), [1801]),
    ]
    return [_ev(i, *r) for i, r in enumerate(rows)]


def write(root: Path) -> Path:
    """Write the synthetic files under ``root``; return the folder."""
    root.mkdir(parents=True, exist_ok=True)
    comp = {
        "name": "Fixture League",
        "wyId": COMPETITION_ID,
        "format": "Domestic league",
        "area": {"name": "Testland", "id": "0", "alpha3code": "TST", "alpha2code": "TS"},
        "type": "club",
    }
    (root / "competitions.json").write_text(json.dumps([comp]))
    teams_data = {}
    for team, side, score in ((HOME, "home", 1), (AWAY, "away", 0)):
        teams_data[str(team)] = {
            "scoreET": 0,
            "coachId": 1,
            "side": side,
            "teamId": team,
            "score": score,
            "scoreP": 0,
            "hasFormation": 1,
            "scoreHT": score,
            "formation": {
                "bench": [],
                "lineup": [
                    {
                        "playerId": pid(team, n),
                        "assists": "0",
                        "goals": "0",
                        "ownGoals": "0",
                        "redCards": "0",
                        "yellowCards": "0",
                    }
                    for n in range(1, 12)
                ],
                "substitutions": "null",  # as in 6 real team-matches
            },
        }
    match = {
        "status": "Played",
        "roundId": 1,
        "gameweek": 1,
        "teamsData": teams_data,
        "seasonId": SEASON_ID,
        "dateutc": "2099-08-10 15:00:00",
        "winner": HOME,
        "venue": "Fixture Park",
        "wyId": MATCH_ID,
        "label": "Home FC - Away FC, 1 - 0",
        "date": "August 10, 2099",
        "groupName": "",
        "referees": [],
        "duration": "Regular",
        "competitionId": COMPETITION_ID,
    }
    (root / "matches_Fixture.json").write_text(json.dumps([match]))
    (root / "events_Fixture.json").write_text(json.dumps(events()))
    teams = [
        {
            "city": "Test",
            "name": n,
            "wyId": t,
            "officialName": n,
            "area": {"name": "Testland"},
            "type": "club",
        }
        for t, n in ((HOME, "Home FC"), (AWAY, "Atl\\u00e9tico Fixture"))
    ]
    (root / "teams.json").write_text(json.dumps(teams))
    players = [
        {
            "wyId": pid(t, n),
            "shortName": f"P. Konat\\u00e9 {t}-{n}",
            "firstName": "P",
            "middleName": "",
            "lastName": f"Konat\\u00e9 {n}",
            "birthDate": "2000-01-01",
            "role": {"code2": "GK" if n == 1 else "MD"},
            "foot": "right",
            "height": 180,
            "weight": 75,
            "birthArea": {"name": "Testland"},
            "passportArea": {"name": "Testland"},
            "currentTeamId": t,
            "currentNationalTeamId": "null",
        }
        for t in (HOME, AWAY)
        for n in range(1, 12)
    ]
    (root / "players.json").write_text(json.dumps(players))
    return root
